def highest_Power_of_2(base: int, value: int) -> int:
    if base <= 1:
        raise ValueError("Base must be greater than 1")
    if value < 1:
        raise ValueError("Value must be positive")
    exponent = 0
    current = 1
    while current < value:
        current *= base
        exponent += 1
    if current != value:
        raise ValueError("Value is not an exact power of the base")
    return exponent
