def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(n: str) -> bool:
        return all(ch == '9' for ch in n)

    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create palindrome by mirroring left to right
    def create_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    # Increment the middle part of the palindrome
    def increment_middle(left: str, odd_length: bool) -> str:
        if odd_length:
            left_num = int(left)
            left_num += 1
            left_str = str(left_num)
            # If length changes, adjust accordingly
            if len(left_str) > len(left):
                # e.g. 999 -> 1000, handle separately
                return left_str, True
            return left_str, False
        else:
            left_num = int(left)
            left_num += 1
            left_str = str(left_num)
            if len(left_str) > len(left):
                return left_str, True
            return left_str, False

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = create_palindrome(left, odd_length)
    palindrome_num = int(palindrome)

    if palindrome_num > num:
        return palindrome_num

    # Need to increment the middle and then mirror again
    left_inc, overflow = increment_middle(left, odd_length)
    if overflow:
        # For cases like 999 -> 1001 handled above, but also numbers like 99999
        # which would have caused left_inc to be longer than original left.
        # In this case, length increases by 1, so build palindrome accordingly:
        if odd_length:
            # length increases by 1, so new length = length +1, which is even
            # left_inc is longer by 1 digit
            return int(create_palindrome(left_inc, False))
        else:
            # length increases by 1 (odd now)
            return int(create_palindrome(left_inc, True))

    palindrome = create_palindrome(left_inc, odd_length)
    return int(palindrome)
