import math

def min_Jumps(d: int, length: int) -> int:
    # If the distance is zero, no jumps are needed
    if d == 0:
        return 0
    # If one jump can cover the distance exactly or more
    if d == length:
        return 1
    if d < length:
        # If one jump is not exactly enough, at least two jumps are required
        return 2
    # Otherwise, calculate minimum number of jumps by ceiling distance/length
    return math.ceil(d / length)
