from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    # Split input string into groups by spaces; if no spaces, treat entire string as one group
    groups = paren_string.split() if ' ' in paren_string else [paren_string]
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
        result.append(max_depth)
    return result
